import base64
import pathlib

FISHING_PATH = pathlib.Path("app/src/main/res/drawable/bg_fishing_pattern.webp")
FARMING_PATH = pathlib.Path("app/src/main/res/drawable/bg_farming_pattern.webp")

FISHING_B64 = """"""

FARMING_B64 = """"""

for path, b64, label in (
    (FISHING_PATH, FISHING_B64, "fishing"),
    (FARMING_PATH, FARMING_B64, "farming"),
):
    if not path.exists():
        raise SystemExit(f"PATCH FAILED: {path} does not exist - refusing to create a new file, only replacing an existing one. No changes made.")
    data = base64.b64decode(b64)
    path.write_bytes(data)
    print(f"Replaced {label} background: {path} ({len(data)} bytes, 480x750 WEBP)")
